1|// Deep import: the pi-utils barrel loads the host native addon, which is
2|// absent on cross-compiling release runners.
3|import { USER_AGENT } from "@oh-my-pi/pi-utils/dirs";
4|import { buildDocsIndexPayload } from "./generate-docs-index";
5|import { createLegacyPiVirtualModulePlugin } from "./legacy-pi-virtual-module";
6|
7|/** Native runtime dependencies always resolved from the on-demand install instead of embedded into compiled binaries. */
8|export const COMPILED_EXTERNAL_DEPENDENCIES: readonly string[] = Object.freeze(["fastembed", "onnxruntime-node"]);
9|
10|/** Inputs shared by local and release coding-agent binary builds. */
11|export interface CodingAgentCompileOptions {
12|	/** Absolute repository root used for package resolution. */
13|	readonly repoRoot: string;
14|	/** Absolute CLI entrypoint. */
15|	readonly entrypoint: string;
16|	/** Absolute standalone executable output path. */
17|	readonly outfile: string;
18|	/** Concrete Transformers.js version baked into the tiny-model worker. */
19|	readonly transformersVersion: string;
20|	/** Optional cross-compilation runtime target. */
21|	readonly target?: Bun.Build.CompileTarget;
22|	/** Optional unmodified Bun executable used as the standalone runtime template. */
23|	readonly executablePath?: string;
24|	/** Match release builds that minify identifiers while retaining names. */
25|	readonly minifyIdentifiers?: boolean;
26|	/** Disable Bun's built-in Darwin signing before the caller re-signs. */
27|	readonly skipBuiltinCodesign?: boolean;
28|}
29|
30|/**
31| * Compile the coding-agent executable with its legacy Pi compatibility module
32| * graph supplied by an in-memory build plugin rather than generated files.
33| */
34|export async function compileCodingAgent(options: CodingAgentCompileOptions): Promise<void> {
35|	const previousCodesignSetting = Bun.env.BUN_NO_CODESIGN_MACHO_BINARY;
36|	if (options.skipBuiltinCodesign) {
37|		Bun.env.BUN_NO_CODESIGN_MACHO_BINARY = "1";
38|	}
39|	try {
40|		const output = await Bun.build({
41|			entrypoints: [options.entrypoint],
42|			root: options.repoRoot,
43|			external: [...COMPILED_EXTERNAL_DEPENDENCIES],
44|			define: {
45|				"process.env.PI_COMPILED": JSON.stringify("true"),
46|				"process.env.PI_TINY_TRANSFORMERS_VERSION": JSON.stringify(options.transformersVersion),
47|				"process.env.PI_DOCS_EMBED": JSON.stringify((await buildDocsIndexPayload()).payload),
48|			},
49|			minify: {
50|				identifiers: options.minifyIdentifiers ?? false,
51|				keepNames: true,
52|			},
53|			plugins: [await createLegacyPiVirtualModulePlugin()],
54|			compile: {
55|				// Bun's process-wide fetch User-Agent default. Any explicit
56|				// provider fingerprint (Anthropic/Codex OAuth) still wins.
57|				execArgv: [`--user-agent=${USER_AGENT}`],
58|				...(options.executablePath
59|					? { executablePath: options.executablePath }
60|					: options.target
61|						? { target: options.target }
62|						: {}),
63|				outfile: options.outfile,
64|				autoloadBunfig: false,
65|				autoloadDotenv: false,
66|				autoloadTsconfig: false,
67|				autoloadPackageJson: false,
68|			},
69|			throw: false,
70|		});
71|		if (!output.success) {
72|			throw new Error(`Coding-agent binary bundle failed:\n${output.logs.map(log => log.message).join("\n")}`);
73|		}
74|	} finally {
75|		if (previousCodesignSetting === undefined) {
76|			delete Bun.env.BUN_NO_CODESIGN_MACHO_BINARY;
77|		} else {
78|			Bun.env.BUN_NO_CODESIGN_MACHO_BINARY = previousCodesignSetting;
79|		}
80|	}
